import routes from '../routes/sidebar'
import { NavLink,  Routes, Link , useLocation , useNavigate} from 'react-router-dom'
import SidebarSubmenu from './SidebarSubmenu';
import XMarkIcon  from '@heroicons/react/24/outline/XMarkIcon'
import { useDispatch } from 'react-redux';
function LeftSidebar({ userRole }) {
    const location = useLocation();
    const navigate = useNavigate(); // Initialize navigate hook

    const close = (e) => {
        document.getElementById('left-sidebar-drawer').click(); // Close sidebar
    }
    const filteredRoutes = routes.filter(route => {
        // Hide dashboard and /app/Users for Teachers
        if ((route.path === "/app/dashboard" || route.path === "/app/Users") && userRole === "Teacher") return false;
        return true;
    });
    const handleNavLinkClick = (path) => {
        close(); // Close sidebar
        navigate(path); // Navigate to the selected route
    }

    return (
        <div className="drawer-side z-30">
            <label htmlFor="left-sidebar-drawer" className="drawer-overlay"></label>
            <ul className="menu pt-2 w-80 bg-base-100 min-h-full text-base-content">
                <button 
                    className="btn btn-ghost bg-base-300 btn-circle z-50 top-0 right-0 mt-4 mr-2 absolute lg:hidden"
                    onClick={() => close()}
                >
                    <XMarkIcon className="h-5 inline-block w-5" />
                </button>

                <li className="mb-2 font-semibold text-xl">
                    <NavLink to="/app/welcome">
                        <img className="mask mask-squircle w-10" src="/download.jpeg" alt=""/>
                        QGenie
                    </NavLink>
                </li>

                {
                   filteredRoutes.map((route, k) => (
                        <li key={k}>
                            {
                                route.submenu ? (
                                    <SidebarSubmenu {...route} />
                                ) : (
                                    <NavLink
                                        end
                                        to={route.path}
                                        onClick={() => handleNavLinkClick(route.path)} // Add onClick handler
                                        className={({ isActive }) => `${isActive ? 'font-semibold bg-base-200' : 'font-normal'}`}
                                    >
                                        {route.icon} {route.name}
                                        {
                                            location.pathname === route.path && (
                                                <span className="absolute inset-y-0 left-0 w-1 rounded-tr-md rounded-br-md bg-primary" aria-hidden="true"></span>
                                            )
                                        }
                                    </NavLink>
                                )
                            }
                        </li>
                    ))
                }

            </ul>
        </div>
    );
}

export default LeftSidebar;